{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 2,
      "verse": 35,
      "source_ref": "2:35",
      "text_ar": "وقال لزوجتيه أداه وزيلة: اسمعوا صوتي يا زوجات لاميك، انتبهن إلى كلماتي، فإنكم تخيلتم وقالتم إنني قتلت رجلاً بجروحي، وطفلاً بخطاي لأنهم لم يرتكبوا عنفاً، لكن اعلموا أنني كبير في السن وشعر رأسي رمادي، وعينيّ ثقيلة من كبر السن، وقد فعلت ذلك دون علم."
    },
    {
      "chapter": 2,
      "verse": 36,
      "source_ref": "2:36",
      "text_ar": "فاستمعت زوجات لاميك إليه في هذا الأمر، وعادوا إليه بنصيحة أبيهن آدم، ولم ينجبن له أطفالاً من ذلك الحين، مدركاتً أن غضب الله كان يتصاعد في تلك الأيام ضد بني البشر، ليهلكهم بمياه الطوفان بسبب شرورهم."
    },
    {
      "chapter": 2,
      "verse": 37,
      "source_ref": "2:37",
      "text_ar": "وعاش مهلال بن كاينان خمسة وستين سنة وأنجب يارد؛ وعاش يارد اثنتين وستين سنة وأنجب أخنوخ."
    },
    {
      "chapter": 3,
      "verse": 1,
      "source_ref": "3:1",
      "text_ar": "وعاش أخنوخ خمسة وستين سنة وأنجب متوشالح؛ وسار أخنوخ مع الله بعد أن أنجب متوشالح، وخدم الرب، واستهين بطُرق الناس الشريرة."
    },
    {
      "chapter": 3,
      "verse": 2,
      "source_ref": "3:2",
      "text_ar": "فكانت روح أخنوخ ملفوفة في تعاليم الرب، في المعرفة والفهم؛ فتقاعس بحكمة عن أبناء الناس، واختفى عنهم لسنوات عديدة."
    },
    {
      "chapter": 3,
      "verse": 3,
      "source_ref": "3:3",
      "text_ar": "وعند انتهاء سنوات عديدة وهو يخدم الرب ويصلي أمامه في بيته، نادى إليه ملاك الرب من السماء، فقال: ها أنا."
    },
    {
      "chapter": 3,
      "verse": 4,
      "source_ref": "3:4",
      "text_ar": "وقال: انهض، اخْرُج من بيتك ومن المكان الذي تختبئ فيه، وظهر أمام أبناء البشر، لكي تعلمهم الطريق الذي يجب أن يسلكوه والعمل الذي يجب أن يؤدوه لدخول سُبُل الله."
    },
    {
      "chapter": 3,
      "verse": 5,
      "source_ref": "3:5",
      "text_ar": "فقام أخنوخ وفق كلمة الرب، فخرج من بيته ومن مكانه ومن الغرفة التي كان يختبئ فيها؛ فذهب إلى أبناء البشر وعلمهم سُبُل الرب، وفي ذلك الوقت جمع أبناء البشر وأطلعهم على تعاليم الرب."
    },
    {
      "chapter": 3,
      "verse": 6,
      "source_ref": "3:6",
      "text_ar": "وأمر بأن يُعلَن في جميع الأماكن التي يسكن فيها أبناء البشر، قائلاً: أين الرجل الذي يرغب في معرفة سُبُل الرب والأعمال الصالحة؟ فليأتِ إلى أخنوخ."
    },
    {
      "chapter": 3,
      "verse": 7,
      "source_ref": "3:7",
      "text_ar": "فاجتمع كل أبناء البشر إليه، لأن كل من أراد ذلك جاء إلى أخنوخ، وحكم أخنوخ على أبناء البشر وفق كلمة الرب، فأتوا وسجدوا له وسمعوا كلمته."
    }
  ]
}
